// Generated by AI
using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Updates the "0/10" text of a bin. Put it on the bin (next to SortingBin), then assign
/// the SortingBin and the label object. The label can be any object that shows text:
/// TextMeshPro, UI Text or the classic 3D TextMesh.
/// </summary>
public class BinCounterLabel : MonoBehaviour
{
    [SerializeField] private SortingBin bin;
    [Tooltip("The object that shows the count (for example the LeanLocalizedText object). Any object with text works.")]
    [SerializeField] private GameObject labelObject;
    [Tooltip("{0} = deposited items, {1} = capacity. Use \\n for a new line.")]
    [SerializeField] private string format = "{0}/{1}";

    private TMP_Text tmpLabel;
    private Text uiLabel;
    private TextMesh meshLabel;

    private void Awake()
    {
        if (bin == null) bin = GetComponentInParent<SortingBin>();
        if (bin == null) bin = GetComponentInChildren<SortingBin>();

        if (bin == null)
        {
            Debug.LogError("BinCounterLabel: assign the SortingBin of this bin.", this);
        }

        if (labelObject == null)
        {
            Debug.LogError("BinCounterLabel: assign the Label Object (the object that shows the count).", this);
            return;
        }

        tmpLabel = labelObject.GetComponentInChildren<TMP_Text>(true);
        uiLabel = labelObject.GetComponentInChildren<Text>(true);
        meshLabel = labelObject.GetComponentInChildren<TextMesh>(true);

        if (tmpLabel == null && uiLabel == null && meshLabel == null)
        {
            Debug.LogError("BinCounterLabel: '" + labelObject.name +
                           "' has no TextMeshPro, UI Text or TextMesh component. Pick the object that really shows the text.",
                           this);
        }
    }

    private void OnEnable()
    {
        if (bin == null) return;
        bin.OnCountChanged += Refresh;
        Refresh(bin.DepositedCount, bin.BinCapacity);
    }

    private void OnDisable()
    {
        if (bin != null) bin.OnCountChanged -= Refresh;
    }

    private void Refresh(int deposited, int capacity)
    {
        string text = string.Format(format.Replace("\\n", "\n"), deposited, capacity);
        if (tmpLabel != null) tmpLabel.text = text;
        if (uiLabel != null) uiLabel.text = text;
        if (meshLabel != null) meshLabel.text = text;
    }
}
